  "tokenized_directions": [
    {
      "step": 1,
      "text": "TAKE {{ing_01|PERFECT GRAPES}} FROM THE VINES, PLACE THEM IN A VESSEL AND POUR {{ing_02|RAIN WATER}} OVER THEM THAT HAS BEEN BOILED DOWN ONE THIRD OF ITS VOLUME."
    },
    {
      "step": 2,
      "text": "THE VESSEL MUST BE PITCHED AND SEALED WITH PLASTER, AND MUST BE KEPT IN A COOL PLACE TO WHICH THE SUN HAS NO ACCESS."
    },
    {
      "step": 3,
      "text": "TREATED IN THIS MANNER, THE {{ing_01|GRAPES}} WILL BE FRESH WHENEVER YOU NEED THEM."
    },
    {
      "step": 4,
      "text": "YOU CAN ALSO SERVE THIS WATER AS HONEY MEAD TO THE SICK."
    },
    {
      "step": 5,
      "text": "ALSO, IF YOU COVER THE {{ing_01|GRAPES}} WITH {{ing_03|BARLEY [bran]}} YOU WILL FIND THEM SOUND AND UNINJURED."
    }
